namespace BinSite.Social.Services;
/// <summary>Original fictional editorial exhibitions, always labelled separately from actual user collections.</summary>
public static class CommunityEditorial
{
 public static readonly EditorialExhibit[] Exhibits=[
  new("A City Inside a Drawer","Everyday traces","This fictional editorial exhibition follows small urban routines through objects found in a drawer. These are invented narratives, not historical findings or user contributions.",[
   new("Worn Bus Pass","Fictional everyday life","Its corner has turned white from being carried in the same pocket every morning. The object measures a routine rather than a journey: people sharing a stop and a time without knowing one another."),
   new("A Single Button","Fictional repair story","The button no longer matches any coat. It was kept because it might become useful; it survived because it recalled the evening someone sewed it on. The object's value moves from use to memory."),
   new("An Empty Key Ring","Fictional moving story","The old house key was returned, but the ring remained. Its worn inscription no longer named a place. It asks which pieces of a home travel with us after we leave."),
   new("A Folded Street Sketch","Fictional navigation note","The sketch does not draw a street to scale. It enlarges the landmarks its maker cared about: a bakery, a green roof and a bench always in shade. Meaning comes before measurement."),
   new("An Unnamed Cafe Receipt","Fictional meeting trace","The receipt records two teas and a glass of water, but none of the conversation. It is displayed to reveal the gap between what is recorded and what is remembered, rather than to prove a grand event."),
   new("A Broken Pencil","Fictional shared workspace","The pencil broke during a meeting and both halves stayed in use. It carries a small story about sharing: sometimes dividing something, sometimes deciding together that it is not finished yet.")]),
  new("Tomorrow's Old Objects","Imaginary archaeology","This fictional editorial collection imagines ordinary objects from a future that has not happened. The stories are original inventions, not scientific or historical findings.",[
   new("A Ticket for Rain","Fictional future","The ticket displays clouds instead of a time. In this imagined city, people reserve quiet minutes to spend in the rain, rather than the rain itself. It asks how we organize the act of waiting."),
   new("A Repairable Screen Label","Fictional future","The label celebrates a thirteenth repair rather than a new product's shine. Beside it are drawings of the hands that repaired it instead of a model number. Ownership becomes a history of care."),
   new("A Map of Silence","Fictional future","This map shows places where someone can sit without speaking at different hours. Some exist for only a few minutes. The object asks how a city might recognize needs that cannot be seen."),
   new("A Shared Shade Ring","Fictional future","A small ring between two trees turns a piece of cloth toward the sun. In the story, nobody owns the shade; everyone adds a knot to maintain it. A shared space becomes something tangible."),
   new("A Notebook of Unfinished Work","Fictional future","Every page holds an unfinished project, and none is labelled a failure. Recording why something stopped allows another person to continue from elsewhere. The exhibition treats incompleteness as an invitation."),
   new("A Memory Bookmark","Fictional future","The bookmark marks a moment in conversation rather than a page. It says only 'listen again here.' This imagined object asks whether remembering means storing every detail or wanting to return.")]),
  new("The Table of Unseen Work","Care and making together","This fictional editorial exhibition makes visible the small acts that enable a shared result. Its original object stories use no real names or personal histories.",[
   new("The Spare Chair","Fictional community gathering","The chair is empty in the photograph. It was kept near the door so a late arrival would not need to look for a place. It represents thought given to someone whose arrival was still uncertain."),
   new("A Task Card in Pencil","Fictional teamwork","The task has changed three times. At the end, 'look at this together' replaces a person's name. The object shows that discussing responsibility is part of making something, just as finishing it is."),
   new("A Cold Cup of Tea","Fictional preparation evening","The cup stood beside the person arranging tables before an event. It makes room for preparation absent from the finished display. The story is about recognizing work rather than celebrating exhaustion."),
   new("A Bilingual Direction Sign","Fictional meeting place","The second language was added so a participant could find the way independently. It presents access as part of the gathering's original design, rather than as an optional decoration."),
   new("Unfinished Meeting Notes","Fictional decision process","The final line names who should be heard next, rather than a decision. Some work needs the right person to be listened to before it can be concluded. The paper records a careful process."),
   new("A Shared Toolbox Lid","Fictional neighborhood workshop","The tools changed over the years; the handwriting on the lid remained. Repairs added scratches and new participants added marks. It preserves ways of caring for something together, not just an inventory.")])
 ];
}
